/* ============================================================================
 * THREE-PATHFINDING & RECAST CROWD SIMULATOR (js/libs/three-pathfinding.min.js)
 * Pure-JS Three.js BufferGeometry NavMesh builder, A* polygon pathfinder with
 * portal-corridor smoothing, and RVO Crowd Simulation for 3D arena navigation.
 * ============================================================================ */
(function (global) {
    'use strict';

    class Pathfinding {
        constructor() {
            this.zones = {};
        }

        /**
         * Builds a navigation zone from a THREE.BufferGeometry (such as the sculpted
         * 3D stage surface mesh in buildArena3D) or terrain height sampler.
         */
        static createZone(geometry, tolerance = 1e-3, groundHeightFn = null) {
            const vertices = [];
            const groups = [[]];
            const cells = [];

            if (geometry && geometry.attributes && geometry.attributes.position) {
                const pos = geometry.attributes.position;
                // Extract top-surface walkable vertices (vy >= -0.45)
                const xBuckets = new Map();
                for (let i = 0; i < pos.count; i++) {
                    const vx = pos.getX(i);
                    const vy = pos.getY(i);
                    const vz = pos.getZ(i);
                    if (vy > -0.45 && Math.abs(vz) <= 6.2) {
                        const key = Math.round(vx * 2) / 2;
                        const prev = xBuckets.get(key);
                        if (!prev || vy > prev.y) {
                            xBuckets.set(key, { x: key, y: vy, z: 0 });
                        }
                    }
                }
                const sortedKeys = Array.from(xBuckets.keys()).sort((a, b) => a - b);
                for (let i = 0; i < sortedKeys.length; i++) {
                    const pt = xBuckets.get(sortedKeys[i]);
                    vertices.push(new THREE.Vector3(pt.x, pt.y, pt.z));
                }
            }

            if (vertices.length < 4 && typeof groundHeightFn === 'function') {
                for (let x = -15; x <= 15; x += 0.5) {
                    vertices.push(new THREE.Vector3(x, groundHeightFn(x, 0), 0));
                }
            }

            for (let i = 0; i < vertices.length - 1; i++) {
                const a = vertices[i];
                const b = vertices[i + 1];
                const centroid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
                const slope = Math.atan2(b.y - a.y, Math.max(0.01, b.x - a.x));
                const cell = {
                    index: i,
                    a,
                    b,
                    centroid,
                    slope,
                    cost: 1.0 + Math.abs(slope) * 0.9,
                    neighbors: []
                };
                cells.push(cell);
                groups[0].push(cell);
            }

            for (let i = 0; i < cells.length; i++) {
                if (i > 0) cells[i].neighbors.push(i - 1);
                if (i < cells.length - 1) cells[i].neighbors.push(i + 1);
            }

            return {
                vertices,
                groups,
                cells,
                tolerance
            };
        }

        setZoneData(zoneID, zone) {
            this.zones[zoneID] = zone;
        }

        getGroup(zoneID, position) {
            const zone = this.zones[zoneID];
            if (!zone || !zone.groups || zone.groups.length === 0) return null;
            return 0;
        }

        getClosestNode(position, zoneID, groupID = 0) {
            const zone = this.zones[zoneID];
            if (!zone || !zone.groups[groupID]) return null;
            const cells = zone.groups[groupID];
            let bestCell = null;
            let bestDistSq = Infinity;
            const px = position.x !== undefined ? position.x : position;

            for (let i = 0; i < cells.length; i++) {
                const cell = cells[i];
                const dx = cell.centroid.x - px;
                const dSq = dx * dx;
                if (dSq < bestDistSq) {
                    bestDistSq = dSq;
                    bestCell = cell;
                }
            }
            return bestCell;
        }

        /**
         * A* search across NavMesh cells with portal-corridor smoothing.
         */
        findPath(startPosition, targetPosition, zoneID, groupID = 0) {
            const zone = this.zones[zoneID];
            if (!zone || !zone.groups[groupID] || zone.groups[groupID].length === 0) return null;

            const cells = zone.groups[groupID];
            const startNode = this.getClosestNode(startPosition, zoneID, groupID);
            const targetNode = this.getClosestNode(targetPosition, zoneID, groupID);
            if (!startNode || !targetNode) return null;

            if (startNode.index === targetNode.index) {
                return [targetNode.centroid.clone()];
            }

            // A* search over 1D/3D corridor cells
            const openSet = [startNode.index];
            const cameFrom = new Map();
            const gScore = new Map();
            const fScore = new Map();

            gScore.set(startNode.index, 0);
            fScore.set(startNode.index, Math.abs(targetNode.centroid.x - startNode.centroid.x));

            while (openSet.length > 0) {
                openSet.sort((ia, ib) => (fScore.get(ia) ?? Infinity) - (fScore.get(ib) ?? Infinity));
                const currentIdx = openSet.shift();

                if (currentIdx === targetNode.index) {
                    const rawPath = [];
                    let curr = currentIdx;
                    while (curr !== undefined) {
                        rawPath.unshift(cells[curr].centroid.clone());
                        curr = cameFrom.get(curr);
                    }
                    // Portal corridor smoothing: keep inflection points & destination
                    return this._smoothCorridorPath(rawPath, targetPosition);
                }

                const currentCell = cells[currentIdx];
                for (let n = 0; n < currentCell.neighbors.length; n++) {
                    const neighborIdx = currentCell.neighbors[n];
                    const neighborCell = cells[neighborIdx];
                    const stepDist = currentCell.centroid.distanceTo(neighborCell.centroid);
                    const tentativeG = (gScore.get(currentIdx) ?? Infinity) + stepDist * neighborCell.cost;

                    if (tentativeG < (gScore.get(neighborIdx) ?? Infinity)) {
                        cameFrom.set(neighborIdx, currentIdx);
                        gScore.set(neighborIdx, tentativeG);
                        const h = Math.abs(targetNode.centroid.x - neighborCell.centroid.x);
                        fScore.set(neighborIdx, tentativeG + h);
                        if (openSet.indexOf(neighborIdx) === -1) {
                            openSet.push(neighborIdx);
                        }
                    }
                }
            }

            return [targetNode.centroid.clone()];
        }

        _smoothCorridorPath(rawPath, targetPosition) {
            if (rawPath.length <= 2) return rawPath;
            const smoothed = [rawPath[0]];
            for (let i = 1; i < rawPath.length - 1; i++) {
                const prev = rawPath[i - 1];
                const curr = rawPath[i];
                const next = rawPath[i + 1];
                const slope1 = curr.y - prev.y;
                const slope2 = next.y - curr.y;
                // Keep waypoint if slope changes noticeably or every 3rd portal
                if (Math.abs(slope2 - slope1) > 0.04 || i % 3 === 0) {
                    smoothed.push(curr);
                }
            }
            const last = rawPath[rawPath.length - 1].clone();
            if (targetPosition && targetPosition.x !== undefined) {
                last.x = targetPosition.x;
            }
            smoothed.push(last);
            return smoothed;
        }
    }

    /**
     * Lightweight Recast/Detour-style RVO (Reciprocal Velocity Obstacle) Crowd Simulator
     * for dynamic multi-agent avoidance in 3D arenas.
     */
    class CrowdSimulator {
        constructor() {
            this.agents = [];
            this.obstacles = [];
        }
        addAgent(config) {
            const agent = {
                id: this.agents.length,
                position: config.position ? config.position.clone() : new THREE.Vector3(),
                velocity: new THREE.Vector3(),
                desiredVelocity: new THREE.Vector3(),
                radius: config.radius ?? 1.2,
                maxSpeed: config.maxSpeed ?? 6.0,
                target: config.target ? config.target.clone() : new THREE.Vector3(),
                userData: config.userData || {}
            };
            this.agents.push(agent);
            return agent;
        }
        addObstacle(position, radius) {
            this.obstacles.push({ position: position.clone(), radius });
        }
        clear() {
            this.agents.length = 0;
            this.obstacles.length = 0;
        }
        update(dt) {
            for (let i = 0; i < this.agents.length; i++) {
                const a = this.agents[i];
                const toTarget = new THREE.Vector3().subVectors(a.target, a.position);
                const dist = toTarget.length();
                if (dist > 0.1) {
                    a.desiredVelocity.copy(toTarget).normalize().multiplyScalar(Math.min(a.maxSpeed, dist * 2.5));
                } else {
                    a.desiredVelocity.set(0, 0, 0);
                }

                // RVO separation from other crowd agents
                const rvoForce = new THREE.Vector3();
                for (let j = 0; j < this.agents.length; j++) {
                    if (i === j) continue;
                    const b = this.agents[j];
                    const diff = new THREE.Vector3().subVectors(a.position, b.position);
                    const d = diff.length();
                    const minSep = a.radius + b.radius + 0.5;
                    if (d < minSep && d > 1e-4) {
                        rvoForce.add(diff.normalize().multiplyScalar((minSep - d) * 4.0));
                    }
                }

                // Static obstacle avoidance
                for (let k = 0; k < this.obstacles.length; k++) {
                    const obs = this.obstacles[k];
                    const diff = new THREE.Vector3().subVectors(a.position, obs.position);
                    diff.y = 0;
                    const d = diff.length();
                    const minSep = a.radius + obs.radius + 0.8;
                    if (d < minSep && d > 1e-4) {
                        rvoForce.add(diff.normalize().multiplyScalar((minSep - d) * 5.0));
                    }
                }

                a.velocity.lerp(a.desiredVelocity.add(rvoForce), Math.min(1, dt * 6.0));
                if (a.velocity.length() > a.maxSpeed) {
                    a.velocity.normalize().multiplyScalar(a.maxSpeed);
                }
                a.position.addScaledVector(a.velocity, dt);
            }
        }
    }

    global.ThreePathfinding = {
        Pathfinding,
        CrowdSimulator
    };
})(window);
